gYo(){return"\u067e\u0632\u06cc\u0634\u06a9 \u0647\u06cc\u0686 \u0644\u06d5 \u0646\u06d5\u0634\u062a\u06d5\u0631\u06af\u06d5\u0631\u06cc\u06cc\u06d5\u06a9 \u0646\u0627\u06a9\u0627\u062a \u0647\u06d5\u062a\u0627 \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u062a\u06d5\u0648\u0627\u0648\u06cc \u062a\u06ce\u0686\u0648\u0648\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5 \u06a9\u06c6\u062f\u06d5\u06a9\u0627\u062a\u06d5\u0648\u06d5\u060c \u0626\u06cc\u0646\u062c\u0627 \u0695\u06ce\u0698\u06d5\u06cc \u062e\u06c6\u06cc \u0644\u06d5\u0648\u06d5\u06cc \u0632\u06cc\u0627\u062a\u0631\u06d5."},
gYB(){return"\u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06cc \u0628\u06d5\u0634\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
gYz(){return"\u0628\u06d5\u062f\u0648\u0627\u062f\u0627\u0686\u0648\u0648\u0646\u06cc \u0628\u06a9\u06d5\u060c \u0626\u06cc\u0646\u062c\u0627 \u0628\u06cc\u062f\u06d5"},
gYA(){return"\u0628\u06d5\u0634\u06cc \u067e\u0632\u06cc\u0634\u06a9 \u0648\u06d5\u06a9 \u0628\u0627\u06b5\u0627\u0646\u0633\u06ce\u06a9 \u06a9\u06c6\u062f\u06d5\u0628\u06ce\u062a\u06d5\u0648\u06d5 \u06a9\u06d5 \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0642\u06d5\u0631\u0632\u0627\u0631\u06d5\u061b \u06a9\u06d5\u0633\u06ce\u06a9 \u0647\u06d5\u0631 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06ce\u06a9 \u062a\u06c6\u0645\u0627\u0631 \u062f\u06d5\u06a9\u0627\u062a. \u067e\u06ce\u0634\u0646\u06cc\u0627\u0631\u06a9\u0631\u0627\u0648."},
gYx(){return"\u062e\u06c6\u06a9\u0627\u0631\u0627\u0646\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u0628\u06a9\u06d5"},
gYy(){return"\u0628\u06d5\u0634\u06cc \u0647\u06d5\u0631 \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9 \u0648\u06d5\u06a9 \u0648\u06d5\u0631\u06af\u06cc\u0631\u0627\u0648 \u0644\u06d5 \u0633\u0646\u062f\u0648\u0642 \u062f\u0627\u062f\u06d5\u0646\u0631\u06ce\u062a \u06a9\u0627\u062a\u06ce\u06a9 \u0646\u06d5\u062e\u06c6\u0634 \u067e\u0627\u0631\u06d5 \u062f\u06d5\u062f\u0627\u062a. \u0647\u06cc\u0686 \u0628\u0627\u06b5\u0627\u0646\u0633\u06ce\u06a9 \u0646\u06cc\u06cc\u06d5 \u0628\u06c6 \u0628\u06d5\u062f\u0648\u0627\u062f\u0627\u0686\u0648\u0648\u0646 \u0648 \u0647\u06cc\u0686 \u0647\u06d5\u0646\u06af\u0627\u0648\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u2014 \u0634\u0627\u0634\u06d5\u06cc \u0642\u0627\u0632\u0627\u0646\u062c\u06cc \u067e\u0632\u06cc\u0634\u06a9\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0628\u06ce\u062a\u06d5 \u0695\u0627\u067e\u06c6\u0631\u062a\u06cc \u062a\u06d5\u0646\u0647\u0627 \u0628\u06c6 \u0628\u06cc\u0646\u06cc\u0646."},
